// Fake payment gateway. The first "failures" refund calls reject.
export function createFakeGateway({ failures = 0 } = {}) {
  const refunds = [];
  let calls = 0;
  return {
    refunds,
    async refund(paymentId, amountCents) {
      await new Promise((r) => setTimeout(r, 1));
      if (++calls <= failures) throw new Error('gateway down');
      const r = { id: 're_' + (refunds.length + 1), paymentId, amountCents };
      refunds.push(r);
      return r;
    },
  };
}

