import { test, expect } from 'bun:test';
import { createFakeGateway } from '../src/gateway.js';
import { refund } from '../src/refunds.js';
const ctx = (capturedCents = 1000) => ({ gateway: createFakeGateway(), payments: new Map([['p1', { capturedCents }]]) });
test('refunds part of a payment', async () => {
  const c = ctx();
  expect(await refund(c, 'p1', 400)).toEqual({ refundId: 're_1', amountCents: 400 });
  expect(c.gateway.refunds.length).toBe(1);
});
test('refunds the full amount', async () => {
  const c = ctx(1000);
  await refund(c, 'p1', 1000);
  expect(c.gateway.refunds[0].amountCents).toBe(1000);
});
test('unknown payment and a refund above the captured amount are rejected', async () => {
  const c = ctx(1000);
  await expect(refund(c, 'nope', 100)).rejects.toThrow();
  await expect(refund(c, 'p1', 1001)).rejects.toThrow();
  expect(c.gateway.refunds.length).toBe(0);
});

