import { test, expect } from 'bun:test';
import { createFakeGateway } from '../src/gateway.js';
import { refund } from '../src/refunds.js';
const ctx = (opts) => ({ gateway: createFakeGateway(opts), payments: new Map([['p1', { capturedCents: 1000 }]]) });
const total = (c) => c.gateway.refunds.reduce((n, r) => n + r.amountCents, 0);
test('partial refunds together never exceed the captured amount', async () => {
  const c = ctx();
  await refund(c, 'p1', 600);
  await expect(refund(c, 'p1', 600)).rejects.toThrow();
  await refund(c, 'p1', 400);
  await expect(refund(c, 'p1', 1)).rejects.toThrow();
  expect(total(c)).toBe(1000);
});
test('two concurrent refunds cannot both go through', async () => {
  const c = ctx();
  const res = await Promise.allSettled([refund(c, 'p1', 600), refund(c, 'p1', 600)]);
  expect(res.filter((r) => r.status === 'fulfilled').length).toBe(1);
  expect(total(c)).toBe(600);
});
test('only whole positive cents are valid', async () => {
  const c = ctx();
  for (const bad of [10.5, -5, NaN, Infinity]) await expect(refund(c, 'p1', bad)).rejects.toThrow();
  expect(c.gateway.refunds.length).toBe(0);
});
test('a failed gateway call does not use up the refundable amount', async () => {
  const c = ctx({ failures: 1 });
  await expect(refund(c, 'p1', 1000)).rejects.toThrow();
  await refund(c, 'p1', 1000);
  expect(total(c)).toBe(1000);
});
